import { expect } from '@playwright/test';
import AxeBuilder from '@axe-core/playwright';

/**
 * Runs an axe scan for WCAG 2.0/2.1/2.2 A & AA against the current page state.
 */
export async function expectNoA11yViolations(page, context = {}) {
  const results = await new AxeBuilder({ page })
    .withTags(['wcag2a', 'wcag2aa', 'wcag21a', 'wcag21aa', 'wcag22aa'])
    .analyze();
  expect(
    results.violations,
    `axe violations: ${results.violations
      .map((v) => `${v.id} (${v.impact}): ${v.nodes.map((n) => n.target).join(', ')}`)
      .join('\n')}`,
  ).toEqual([]);
}

/** Sizes offered on the page; sold-out sizes must not be selectable. */
export const SIZES = ['US 7', 'US 8', 'US 9', 'US 10', 'US 11', 'US 12'];
export const SOLD_OUT_SIZES = ['US 9', 'US 11'];

