import { test, expect } from '@playwright/test';
import { expectNoA11yViolations } from './helpers.js';

// Requirement: Store — the shopper sees the store name and how many items are
// in their cart.
// Requirement: Menu — the shopper can go to the store's main sections, such as
// men, women and kids, from the top of the page.

test.describe('Store header', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/');
  });

  test('shows the store name in the banner landmark', async ({ page }) => {
    const banner = page.getByRole('banner');
    await expect(banner).toBeVisible();
    await expect(banner).toContainText('Stride');
  });

  test('shows the cart with an item count', async ({ page }) => {
    const cart = page.getByRole('link', { name: /cart/i });
    await expect(cart).toBeVisible();
    // The shopper can see how many items are in the cart.
    await expect(cart).toContainText(/\d+/);
    await expect(cart).toHaveAttribute('href', /.+/);
  });

  test('main navigation links to men, women and kids sections', async ({
    page,
  }) => {
    const nav = page.getByRole('navigation', { name: /main/i });
    await expect(nav).toBeVisible();
    for (const section of ['Men', 'Women', 'Kids']) {
      const link = nav.getByRole('link', { name: section, exact: true });
      await expect(link).toBeVisible();
      await expect(link).toHaveAttribute('href', /.+/);
    }
  });

  test('header is reachable and operable by keyboard', async ({ page }) => {
    await page.keyboard.press('Tab');
    // First focusable element is inside the banner (skip link or store name).
    await expect(page.locator(':focus')).toBeVisible();
  });

  test('header has no WCAG 2.2 AA violations', async ({ page }) => {
    await expectNoA11yViolations(page);
  });
});

