import { test, expect } from '@playwright/test';

// Requirement: Path — the shopper sees where the shoe sits in the store, such
// as Shop, Trail, Trail Runner 2, and can go back to any earlier step.

test.describe('Breadcrumb path', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/');
  });

  test('shows the full path in a breadcrumb navigation landmark', async ({
    page,
  }) => {
    const breadcrumb = page.getByRole('navigation', { name: /breadcrumb/i });
    await expect(breadcrumb).toBeVisible();
    await expect(breadcrumb).toContainText('Shop');
    await expect(breadcrumb).toContainText('Trail');
    await expect(breadcrumb).toContainText('Trail Runner 2');
  });

  test('earlier steps are links the shopper can go back to', async ({
    page,
  }) => {
    const breadcrumb = page.getByRole('navigation', { name: /breadcrumb/i });
    for (const step of ['Shop', 'Trail']) {
      const link = breadcrumb.getByRole('link', { name: step, exact: true });
      await expect(link).toBeVisible();
      await expect(link).toHaveAttribute('href', /.+/);
    }
  });

  test('current step is marked as the current page and is not a link', async ({
    page,
  }) => {
    const breadcrumb = page.getByRole('navigation', { name: /breadcrumb/i });
    // APG breadcrumb: last item has aria-current="page" and is not actionable.
    const current = breadcrumb.getByText('Trail Runner 2', { exact: true });
    await expect(current).toHaveAttribute('aria-current', 'page');
    await expect(
      breadcrumb.getByRole('link', { name: 'Trail Runner 2' }),
    ).toHaveCount(0);
  });

  test('path items are presented in order', async ({ page }) => {
    const breadcrumb = page.getByRole('navigation', { name: /breadcrumb/i });
    const text = await breadcrumb.textContent();
    const shopIdx = text.indexOf('Shop');
    const trailIdx = text.indexOf('Trail');
    const productIdx = text.indexOf('Trail Runner 2');
    expect(shopIdx).toBeGreaterThanOrEqual(0);
    expect(trailIdx).toBeGreaterThan(shopIdx);
    expect(productIdx).toBeGreaterThan(trailIdx);
  });
});

