import { test, expect } from '@playwright/test';

// Requirement: Photos — the shopper sees one photo of the shoe at a time and
// moves to the next or previous one, going back to the first after the last.

const PHOTO_COUNT = 3;

test.describe('Photo carousel', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/');
  });

  function carousel(page) {
    return page.getByRole('region', { name: /product photos/i });
  }

  function currentPhoto(page) {
    return carousel(page).getByRole('img', { name: /trail runner 2/i });
  }

  test('shows exactly one photo of the shoe at a time', async ({ page }) => {
    await expect(carousel(page)).toBeVisible();
    await expect(currentPhoto(page)).toHaveCount(1);
    await expect(currentPhoto(page)).toBeVisible();
  });

  test('indicates which photo is shown out of the total', async ({ page }) => {
    await expect(carousel(page)).toContainText(`1 of ${PHOTO_COUNT}`);
  });

  test('next button moves to the next photo', async ({ page }) => {
    await carousel(page)
      .getByRole('button', { name: /next/i })
      .click();
    await expect(carousel(page)).toContainText(`2 of ${PHOTO_COUNT}`);
  });

  test('previous button moves to the previous photo', async ({ page }) => {
    await carousel(page)
      .getByRole('button', { name: /next/i })
      .click();
    await carousel(page)
      .getByRole('button', { name: /previous/i })
      .click();
    await expect(carousel(page)).toContainText(`1 of ${PHOTO_COUNT}`);
  });

  test('wraps back to the first photo after the last', async ({ page }) => {
    for (let i = 0; i < PHOTO_COUNT; i++) {
      await carousel(page)
        .getByRole('button', { name: /next/i })
        .click();
    }
    await expect(carousel(page)).toContainText(`1 of ${PHOTO_COUNT}`);
  });

  test('wraps to the last photo when going previous from the first', async ({
    page,
  }) => {
    await carousel(page)
      .getByRole('button', { name: /previous/i })
      .click();
    await expect(carousel(page)).toContainText(`${PHOTO_COUNT} of ${PHOTO_COUNT}`);
  });

  test('each photo has a descriptive accessible name', async ({ page }) => {
    for (let i = 1; i <= PHOTO_COUNT; i++) {
      await expect(currentPhoto(page)).toHaveAccessibleName(/photo \d+/i);
      await carousel(page)
        .getByRole('button', { name: /next/i })
        .click();
    }
  });

  test('carousel controls are keyboard operable and keep focus', async ({
    page,
  }) => {
    const next = carousel(page).getByRole('button', { name: /next/i });
    await next.focus();
    await page.keyboard.press('Enter');
    await expect(carousel(page)).toContainText(`2 of ${PHOTO_COUNT}`);
    // Focus is not lost when the photo changes.
    await expect(next).toBeFocused();
  });
});

