import { test, expect } from '@playwright/test';

// Requirement: Price — the shopper sees the price and can point at a small "i"
// next to it to learn that it includes taxes.

test.describe('Price', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/');
  });

  test('shows the price of the shoe', async ({ page }) => {
    await expect(
      page.getByRole('heading', { name: 'Trail Runner 2', level: 1 }),
    ).toBeVisible();
    await expect(page.getByText(/\$\s?120/)).toBeVisible();
  });

  test('has an info button next to the price with an accessible name', async ({
    page,
  }) => {
    const info = page.getByRole('button', { name: /price information/i });
    await expect(info).toBeVisible();
  });

  test('pointing at the info reveals a tooltip saying taxes are included', async ({
    page,
  }) => {
    const info = page.getByRole('button', { name: /price information/i });
    await info.hover();
    const tooltip = page.getByRole('tooltip');
    await expect(tooltip).toBeVisible();
    await expect(tooltip).toContainText(/tax(es)?/i);
  });

  test('focusing the info button also reveals the tooltip (keyboard access)', async ({
    page,
  }) => {
    const info = page.getByRole('button', { name: /price information/i });
    await info.focus();
    const tooltip = page.getByRole('tooltip');
    await expect(tooltip).toBeVisible();
    // APG tooltip: the trigger references the tooltip content.
    const describedBy = await info.getAttribute('aria-describedby');
    expect(describedBy).toBeTruthy();
    await expect(page.locator(`#${describedBy}`)).toContainText(/tax(es)?/i);
  });

  test('Escape dismisses the tooltip', async ({ page }) => {
    const info = page.getByRole('button', { name: /price information/i });
    await info.focus();
    await expect(page.getByRole('tooltip')).toBeVisible();
    await page.keyboard.press('Escape');
    await expect(page.getByRole('tooltip')).toBeHidden();
  });
});

