import { test, expect } from '@playwright/test';

// Requirement: Color — the shopper can choose blue, black or grey; only the
// chosen color shows until they change it, each with a round swatch.

const COLORS = ['Blue', 'Black', 'Grey'];

test.describe('Color picker', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/');
  });

  function colorGroup(page) {
    return page.getByRole('radiogroup', { name: /color/i });
  }

  test('offers blue, black and grey as radio choices in a group', async ({
    page,
  }) => {
    const group = colorGroup(page);
    await expect(group).toBeVisible();
    for (const color of COLORS) {
      await expect(
        group.getByRole('radio', { name: color, exact: true }),
      ).toBeVisible();
    }
  });

  test('each color option has a round swatch', async ({ page }) => {
    for (const color of COLORS) {
      const swatch = page.getByTestId(`swatch-${color.toLowerCase()}`);
      await expect(swatch).toBeVisible();
      const box = await swatch.boundingBox();
      // Round: square box with a border-radius of at least 50%.
      expect(Math.abs(box.width - box.height)).toBeLessThanOrEqual(1);
      const radius = await swatch.evaluate(
        (el) => getComputedStyle(el).borderRadius,
      );
      const radiusPx = parseFloat(radius);
      expect(radiusPx).toBeGreaterThanOrEqual(box.width / 2 - 1);
    }
  });

  test('only the chosen color is shown as selected until it changes', async ({
    page,
  }) => {
    const group = colorGroup(page);
    await group.getByRole('radio', { name: 'Blue' }).check();
    await expect(group.getByRole('radio', { name: 'Blue' })).toBeChecked();
    await expect(
      group.getByRole('radio', { name: 'Black' }),
    ).not.toBeChecked();
    await expect(group.getByRole('radio', { name: 'Grey' })).not.toBeChecked();

    // The chosen color is the only one shown to the shopper.
    await expect(page.getByText(/selected color: blue/i)).toBeVisible();
    await expect(page.getByText(/selected color: black/i)).toBeHidden();
    await expect(page.getByText(/selected color: grey/i)).toBeHidden();

    await group.getByRole('radio', { name: 'Grey' }).check();
    await expect(group.getByRole('radio', { name: 'Grey' })).toBeChecked();
