import { test, expect } from '@playwright/test';
import { SIZES, SOLD_OUT_SIZES } from './helpers.js';

// Requirement: Size — the shopper picks one size from a list that only opens
// when they want to change it; only the chosen size shows, and sold-out sizes
// can't be picked.
// Pattern: APG collapsible listbox (button with aria-haspopup="listbox").

test.describe('Size selector', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/');
  });

  function sizeButton(page) {
    return page.getByRole('button', { name: /^size/i });
  }

  test('list stays closed until the shopper wants to change the size', async ({
    page,
  }) => {
    await expect(sizeButton(page)).toHaveAttribute('aria-haspopup', 'listbox');
    await expect(sizeButton(page)).toHaveAttribute('aria-expanded', 'false');
    await expect(page.getByRole('listbox')).toBeHidden();
  });

  test('opens on click and shows all sizes', async ({ page }) => {
    await sizeButton(page).click();
    await expect(sizeButton(page)).toHaveAttribute('aria-expanded', 'true');
    const listbox = page.getByRole('listbox', { name: /size/i });
    await expect(listbox).toBeVisible();
    for (const size of SIZES) {
      await expect(
        listbox.getByRole('option', { name: size, exact: true }),
      ).toBeVisible();
    }
  });

  test('only the chosen size shows once picked, and the list closes', async ({
    page,
  }) => {
    await sizeButton(page).click();
    await page
      .getByRole('listbox', { name: /size/i })
      .getByRole('option', { name: 'US 8', exact: true })
      .click();
    await expect(page.getByRole('listbox')).toBeHidden();
    await expect(sizeButton(page)).toContainText('US 8');
    // Other sizes are not shown while the list is closed.
    await expect(page.getByText('US 7', { exact: true })).toBeHidden();
  });

  test('sold-out sizes are marked and cannot be picked', async ({ page }) => {
    await sizeButton(page).click();
    const listbox = page.getByRole('listbox', { name: /size/i });
    for (const size of SOLD_OUT_SIZES) {
      const option = listbox.getByRole('option', { name: new RegExp(size) });
      await expect(option).toHaveAttribute('aria-disabled', 'true');
      await expect(option).toContainText(/sold out/i);
      // Clicking a sold-out size does not select it and keeps the list open.
      await option.click({ force: true });
      await expect(listbox).toBeVisible();
      await expect(sizeButton(page)).not.toContainText(size);
    }
  });

  test('keyboard: opens with ArrowDown, moves with arrows, selects with Enter', async ({
    page,
  }) => {
    await sizeButton(page).focus();
    await page.keyboard.press('ArrowDown');
    const listbox = page.getByRole('listbox', { name: /size/i });
    await expect(listbox).toBeVisible();
    // Focus is on an option (APG: aria-activedescendant or roving focus).
    await page.keyboard.press('ArrowDown');
    await page.keyboard.press('Enter');
    await expect(listbox).toBeHidden();
    // The second size in the list was chosen.
    await expect(sizeButton(page)).toContainText(SIZES[1]);
    // Focus returns to the button after selection.
    await expect(sizeButton(page)).toBeFocused();
  });

  test('keyboard: Escape closes the list and returns focus to the button', async ({
    page,
  }) => {
    await sizeButton(page).click();
    await expect(page.getByRole('listbox', { name: /size/i })).toBeVisible();
    await page.keyboard.press('Escape');
    await expect(page.getByRole('listbox')).toBeHidden();
    await expect(sizeButton(page)).toBeFocused();
    await expect(sizeButton(page)).toHaveAttribute('aria-expanded', 'false');
  });

  test('sold-out sizes are skipped over / not selectable via keyboard', async ({
    page,
  }) => {
    await sizeButton(page).focus();
    await page.keyboard.press('ArrowDown');
    const listbox = page.getByRole('listbox', { name: /size/i });
    // Navigate to a sold-out size and try to select it.
    const soldOut = listbox.getByRole('option', {
      name: new RegExp(SOLD_OUT_SIZES[0]),
    });
    await soldOut.focus();
    await page.keyboard.press('Enter');
    await expect(sizeButton(page)).not.toContainText(SOLD_OUT_SIZES[0]);
  });
});

