import { test, expect } from '@playwright/test';
import { expectNoA11yViolations } from './helpers.js';

// Requirement: Size guide — the shopper can open a size chart over the page
// from next to the size, enter their foot length and choose US or EU to get
// their size, and must close it to continue.
// Pattern: APG modal dialog.

test.describe('Size guide dialog', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/');
  });

  function trigger(page) {
    return page.getByRole('button', { name: /size guide/i });
  }

  function dialog(page) {
    return page.getByRole('dialog', { name: /size guide/i });
  }

  test('a size guide button sits next to the size selector', async ({
    page,
  }) => {
    await expect(trigger(page)).toBeVisible();
  });

  test('opens a modal dialog over the page', async ({ page }) => {
    await trigger(page).click();
    const dlg = dialog(page);
    await expect(dlg).toBeVisible();
    await expect(dlg).toHaveAttribute('aria-modal', 'true');
    // Focus moves into the dialog.
    await expect(dlg.locator(':focus')).toBeVisible();
  });

  test('the shopper enters foot length and chooses US or EU to get a size', async ({
    page,
  }) => {
    await trigger(page).click();
    const dlg = dialog(page);

    const unitGroup = dlg.getByRole('radiogroup', { name: /unit/i });
    await expect(unitGroup.getByRole('radio', { name: 'US' })).toBeVisible();
    await expect(unitGroup.getByRole('radio', { name: 'EU' })).toBeVisible();

    await dlg.getByLabel(/foot length/i).fill('26');
    await unitGroup.getByRole('radio', { name: 'US' }).check();
    await expect(dlg).toContainText(/your size: us 8/i);

    await unitGroup.getByRole('radio', { name: 'EU' }).check();
    await expect(dlg).toContainText(/your size: eu 41/i);
  });

  test('the dialog shows a size chart', async ({ page }) => {
    await trigger(page).click();
    const dlg = dialog(page);
    await expect(dlg.getByRole('table')).toBeVisible();
    await expect(dlg.getByRole('columnheader', { name: /us/i })).toBeVisible();
    await expect(dlg.getByRole('columnheader', { name: /eu/i })).toBeVisible();
  });

  test('the shopper must close the dialog to continue (modal)', async ({
    page,
  }) => {
    await trigger(page).click();
    await expect(dialog(page)).toBeVisible();
    // Content behind the dialog is inert: it cannot receive keyboard focus.
    const addToCart = page.getByRole('button', { name: /add to cart/i });
    await expect(addToCart).not.toBeFocused();
    // Tab cycles inside the dialog and never leaves it.
    for (let i = 0; i < 20; i++) {
      await page.keyboard.press('Tab');
      const inside = await page.evaluate(() => {
        const dlg = document.querySelector('[role="dialog"]');
        return dlg && dlg.contains(document.activeElement);
      });
      expect(inside).toBe(true);
    }
  });

  test('close button closes the dialog and returns focus to the trigger', async ({
    page,
  }) => {
    await trigger(page).click();
    await dialog(page)
      .getByRole('button', { name: /close/i })
      .click();
    await expect(dialog(page)).toBeHidden();
    await expect(trigger(page)).toBeFocused();
  });

  test('Escape closes the dialog and returns focus to the trigger', async ({
    page,
  }) => {
    await trigger(page).click();
    await expect(dialog(page)).toBeVisible();
    await page.keyboard.press('Escape');
    await expect(dialog(page)).toBeHidden();
    await expect(trigger(page)).toBeFocused();
  });

  test('open dialog has no WCAG 2.2 AA violations', async ({ page }) => {
    await trigger(page).click();
    await expect(dialog(page)).toBeVisible();
    await expectNoA11yViolations(page);
  });
});

