    await page.goto('/');
  });

  function quantity(page) {
    return page.getByRole('spinbutton', { name: /quantity/i });
  }

  test('starts at one pair', async ({ page }) => {
    await expect(quantity(page)).toHaveValue('1');
  });

  test('the shopper can type the number of pairs', async ({ page }) => {
    await quantity(page).fill('3');
    await expect(quantity(page)).toHaveValue('3');
  });

  test('increase and decrease buttons change the quantity by one', async ({
    page,
  }) => {
    await page.getByRole('button', { name: /increase quantity/i }).click();
    await expect(quantity(page)).toHaveValue('2');
    await page.getByRole('button', { name: /increase quantity/i }).click();
    await expect(quantity(page)).toHaveValue('3');
    await page.getByRole('button', { name: /decrease quantity/i }).click();
    await expect(quantity(page)).toHaveValue('2');
  });

  test('quantity never goes below one', async ({ page }) => {
    await page.getByRole('button', { name: /decrease quantity/i }).click();
    await expect(quantity(page)).toHaveValue('1');
  });

  test('arrow keys on the spinbutton change the quantity by one', async ({
    page,
  }) => {
    await quantity(page).focus();
    await page.keyboard.press('ArrowUp');
    await expect(quantity(page)).toHaveValue('2');
    await page.keyboard.press('ArrowDown');
    await expect(quantity(page)).toHaveValue('1');
  });
});

