import { test, expect } from '@playwright/test';

// Requirement: Add to cart — the shopper adds the shoe to the cart and sees a
// confirmation; without a size they are asked to pick one.

test.describe('Add to cart', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/');
  });

  function sizeButton(page) {
    return page.getByRole('button', { name: /^size/i });
  }

  async function pickSize(page, size) {
    await sizeButton(page).click();
    await page
      .getByRole('listbox', { name: /size/i })
      .getByRole('option', { name: size, exact: true })
      .click();
  }

  test('adding without a size asks the shopper to pick one', async ({
    page,
  }) => {
    await page.getByRole('button', { name: /add to cart/i }).click();
    // The request is announced assertively and does not get lost.
    const alert = page.getByRole('alert');
    await expect(alert).toBeVisible();
    await expect(alert).toContainText(/please (select|pick|choose) a size/i);
    // Nothing was added to the cart.
    const cart = page.getByRole('link', { name: /cart/i });
    await expect(cart).toContainText(/0/);
    // Focus moves to the size selector so the shopper can fix the problem.
    await expect(sizeButton(page)).toBeFocused();
  });

  test('adding with a size shows a confirmation', async ({ page }) => {
    await pickSize(page, 'US 8');
    await page.getByRole('button', { name: /add to cart/i }).click();
    // Polite live region announces the confirmation.
    const status = page.getByRole('status');
    await expect(status).toBeVisible();
    await expect(status).toContainText(/added to cart/i);
  });

  test('the cart count increases by the chosen quantity', async ({ page }) => {
    await pickSize(page, 'US 8');
    await page.getByRole('spinbutton', { name: /quantity/i }).fill('2');
    const cart = page.getByRole('link', { name: /cart/i });
    await expect(cart).toContainText(/0/);
    await page.getByRole('button', { name: /add to cart/i }).click();
    await expect(cart).toContainText(/2/);
  });

  test('the size prompt clears once a size is picked and added', async ({
    page,
  }) => {
    await page.getByRole('button', { name: /add to cart/i }).click();
    await expect(page.getByRole('alert')).toBeVisible();
    await pickSize(page, 'US 10');
    await page.getByRole('button', { name: /add to cart/i }).click();
    await expect(page.getByRole('alert')).toBeHidden();
    await expect(page.getByRole('status')).toContainText(/added to cart/i);
  });
});

