import { test, expect } from '@playwright/test';

// Requirement: Wishlist — the shopper can save or unsave the shoe with a
// heart.
// Pattern: APG toggle button (aria-pressed).

test.describe('Wishlist', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/');
  });

  function wishlist(page) {
    return page.getByRole('button', { name: /wishlist/i });
  }

  test('has a wishlist toggle button with a heart', async ({ page }) => {
    const button = wishlist(page);
    await expect(button).toBeVisible();
    // The heart is part of the control (icon or text), not a bare image.
    await expect(button.locator('[data-icon="heart"]')).toBeVisible();
  });

  test('saves the shoe and communicates the pressed state', async ({
    page,
  }) => {
    const button = wishlist(page);
    await expect(button).toHaveAttribute('aria-pressed', 'false');
    await button.click();
    await expect(button).toHaveAttribute('aria-pressed', 'true');
  });

  test('unsaves the shoe when toggled again', async ({ page }) => {
    const button = wishlist(page);
    await button.click();
    await button.click();
    await expect(button).toHaveAttribute('aria-pressed', 'false');
  });

  test('is operable with the keyboard', async ({ page }) => {
    const button = wishlist(page);
    await button.focus();
    await page.keyboard.press('Enter');
    await expect(button).toHaveAttribute('aria-pressed', 'true');
    await page.keyboard.press('Space');
    await expect(button).toHaveAttribute('aria-pressed', 'false');
  });
});

