import { test, expect } from '@playwright/test';

// Requirement: More information — details, reviews and shipping sit side by
// side below everything, with one section shown at a time.
// Pattern: APG tabs.

const TABS = ['Details', 'Reviews', 'Shipping'];

test.describe('More information tabs', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/');
  });

  function tablist(page) {
    return page.getByRole('tablist', { name: /product information/i });
  }

  test('details, reviews and shipping sit side by side as tabs', async ({
    page,
  }) => {
    const list = tablist(page);
    await expect(list).toBeVisible();
    for (const name of TABS) {
      await expect(
        list.getByRole('tab', { name, exact: true }),
      ).toBeVisible();
    }
    // Side by side: tabs share roughly the same vertical position.
    const boxes = await Promise.all(
      TABS.map((name) =>
        list.getByRole('tab', { name, exact: true }).boundingBox(),
      ),
    );
    expect(Math.abs(boxes[0].y - boxes[1].y)).toBeLessThanOrEqual(2);
    expect(Math.abs(boxes[1].y - boxes[2].y)).toBeLessThanOrEqual(2);
  });

  test('only one section is shown at a time', async ({ page }) => {
    const list = tablist(page);
    // Details is selected by default.
    await expect(
      list.getByRole('tab', { name: 'Details' }),
    ).toHaveAttribute('aria-selected', 'true');
    await expect(
      page.getByRole('tabpanel', { name: 'Details' }),
    ).toBeVisible();
    await expect(
      page.getByRole('tabpanel', { name: 'Reviews' }),
    ).toBeHidden();
    await expect(
      page.getByRole('tabpanel', { name: 'Shipping' }),
    ).toBeHidden();

    await list.getByRole('tab', { name: 'Reviews' }).click();
    await expect(
      page.getByRole('tabpanel', { name: 'Reviews' }),
    ).toBeVisible();
    await expect(
      page.getByRole('tabpanel', { name: 'Details' }),
    ).toBeHidden();
  });

  test('each tabpanel is labelled by its tab', async ({ page }) => {
    for (const name of TABS) {
      const tab = tablist(page).getByRole('tab', { name, exact: true });
      const controls = await tab.getAttribute('aria-controls');
      expect(controls).toBeTruthy();
      await expect(page.locator(`#${controls}`)).toHaveAttribute(
        'role',
        'tabpanel',
      );
    }
  });

  test('arrow keys move between tabs (APG tabs keyboard interaction)', async ({
    page,
  }) => {
    const list = tablist(page);
    await list.getByRole('tab', { name: 'Details' }).click();
    await page.keyboard.press('ArrowRight');
    const reviews = list.getByRole('tab', { name: 'Reviews' });
    await expect(reviews).toBeFocused();
    // Only the selected tab is in the tab order.
    await expect(reviews).toHaveAttribute('tabindex', /0|-1/);
    await page.keyboard.press('ArrowRight');
    await expect(list.getByRole('tab', { name: 'Shipping' })).toBeFocused();
    // Wraps around to the first tab.
    await page.keyboard.press('ArrowRight');
    await expect(list.getByRole('tab', { name: 'Details' })).toBeFocused();
  });

  test('activating a tab from the keyboard shows its section', async ({
    page,
  }) => {
    const list = tablist(page);
    await list.getByRole('tab', { name: 'Details' }).focus();
    await page.keyboard.press('ArrowRight');
    await page.keyboard.press('Enter');
    await expect(
      page.getByRole('tabpanel', { name: 'Reviews' }),
    ).toBeVisible();
  });
});

