import { test, expect } from '@playwright/test';

// Requirement: Questions — a few common questions about the shoe, each with
// its answer hidden until the shopper opens it.
// Pattern: APG accordion.

const QUESTIONS = [
  'Is the Trail Runner 2 waterproof?',
  'How much does the shoe weigh?',
  'Can I return the shoes if they do not fit?',
];

test.describe('Common questions accordion', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/');
  });

  test('shows a few common questions about the shoe', async ({ page }) => {
    const faq = page.getByRole('region', { name: /questions/i });
    await expect(faq).toBeVisible();
    for (const question of QUESTIONS) {
      await expect(
        faq.getByRole('button', { name: question }),
      ).toBeVisible();
    }
  });

  test('answers are hidden until the shopper opens a question', async ({
    page,
  }) => {
    const faq = page.getByRole('region', { name: /questions/i });
    for (const question of QUESTIONS) {
      const button = faq.getByRole('button', { name: question });
      await expect(button).toHaveAttribute('aria-expanded', 'false');
      const panelId = await button.getAttribute('aria-controls');
      expect(panelId).toBeTruthy();
      await expect(page.locator(`#${panelId}`)).toBeHidden();
    }
  });

  test('opening a question reveals its answer', async ({ page }) => {
    const faq = page.getByRole('region', { name: /questions/i });
    const button = faq.getByRole('button', { name: QUESTIONS[0] });
    await button.click();
    await expect(button).toHaveAttribute('aria-expanded', 'true');
    const panelId = await button.getAttribute('aria-controls');
    const panel = page.locator(`#${panelId}`);
    await expect(panel).toBeVisible();
    await expect(panel).not.toBeEmpty();
  });

  test('each question opens independently', async ({ page }) => {
    const faq = page.getByRole('region', { name: /questions/i });
    const first = faq.getByRole('button', { name: QUESTIONS[0] });
    const second = faq.getByRole('button', { name: QUESTIONS[1] });
    await first.click();
    await second.click();
    await expect(first).toHaveAttribute('aria-expanded', 'true');
    await expect(second).toHaveAttribute('aria-expanded', 'true');
    // Opening again closes it.
    await first.click();
    await expect(first).toHaveAttribute('aria-expanded', 'false');
    await expect(second).toHaveAttribute('aria-expanded', 'true');
  });

  test('question buttons are keyboard operable', async ({ page }) => {
    const faq = page.getByRole('region', { name: /questions/i });
    const button = faq.getByRole('button', { name: QUESTIONS[2] });
    await button.focus();
    await page.keyboard.press('Enter');
    await expect(button).toHaveAttribute('aria-expanded', 'true');
    await page.keyboard.press('Space');
    await expect(button).toHaveAttribute('aria-expanded', 'false');
  });
});

