import { test, expect } from '@playwright/test';

// Requirement: Bottom of the page — the shopper finds customer help, company
// and social media links.

test.describe('Footer', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/');
  });

  test('footer is the contentinfo landmark', async ({ page }) => {
    await expect(page.getByRole('contentinfo')).toBeVisible();
  });

  test('offers customer help links', async ({ page }) => {
    const footer = page.getByRole('contentinfo');
    for (const name of ['Contact us', 'FAQ', 'Returns']) {
      const link = footer.getByRole('link', { name, exact: true });
      await expect(link).toBeVisible();
      await expect(link).toHaveAttribute('href', /.+/);
    }
  });

  test('offers company links', async ({ page }) => {
    const footer = page.getByRole('contentinfo');
    for (const name of ['About Stride', 'Careers', 'Press']) {
      const link = footer.getByRole('link', { name, exact: true });
      await expect(link).toBeVisible();
      await expect(link).toHaveAttribute('href', /.+/);
    }
  });

  test('offers social media links with accessible names', async ({ page }) => {
    const footer = page.getByRole('contentinfo');
    for (const name of ['Instagram', 'Facebook', 'YouTube']) {
      const link = footer.getByRole('link', { name, exact: true });
      await expect(link).toBeVisible();
      await expect(link).toHaveAttribute('href', /.+/);
    }
  });

  test('footer link groups have headings for orientation', async ({ page }) => {
    const footer = page.getByRole('contentinfo');
    for (const heading of ['Customer help', 'Company', 'Social media']) {
      await expect(
        footer.getByRole('heading', { name: heading }),
      ).toBeVisible();
    }
  });
});

