import { test, expect } from '@playwright/test';
import { expectNoA11yViolations } from './helpers.js';

// Cross-cutting: WCAG 2.2 AA conformance and keyboard access for the whole page.

test.describe('Accessibility (WCAG 2.2 AA)', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/');
  });

  test('page has no automatically detectable WCAG 2.2 AA violations', async ({
    page,
  }) => {
    await expectNoA11yViolations(page);
  });

  test('page has exactly one h1 naming the product', async ({ page }) => {
    const h1 = page.getByRole('heading', { level: 1 });
    await expect(h1).toHaveCount(1);
    await expect(h1).toContainText('Trail Runner 2');
  });

  test('page is organised in landmarks: banner, main, contentinfo', async ({
    page,
  }) => {
    await expect(page.getByRole('banner')).toHaveCount(1);
    await expect(page.getByRole('main')).toHaveCount(1);
    await expect(page.getByRole('contentinfo')).toHaveCount(1);
  });

  test('the whole page can be used with the keyboard alone', async ({
    page,
  }) => {
    // Every focus stop lands on a visible, operable element.
    for (let i = 0; i < 40; i++) {
      await page.keyboard.press('Tab');
      const focused = page.locator(':focus');
      await expect(focused).toBeVisible();
    }
  });

  test('keyboard focus is always visible (WCAG 2.4.7 / 2.4.13)', async ({
    page,
  }) => {
    await page.keyboard.press('Tab');
    const indicator = await page.evaluate(() => {
      const el = document.activeElement;
      const style = getComputedStyle(el);
      const outlineVisible =
        style.outlineStyle !== 'none' && parseFloat(style.outlineWidth) > 0;
      const shadowVisible =
        style.boxShadow !== 'none' && style.boxShadow !== '';
      return { outlineVisible, shadowVisible, tag: el.tagName };
    });
    expect(
      indicator.outlineVisible || indicator.shadowVisible,
      `focused <${indicator.tag}> has no visible focus indicator`,
    ).toBe(true);
  });

  test('no positive tabindex values anywhere (WCAG 2.4.3 focus order)', async ({
    page,
  }) => {
    const offenders = await page.evaluate(() =>
      Array.from(document.querySelectorAll('[tabindex]'))
        .filter((el) => parseInt(el.getAttribute('tabindex'), 10) > 0)
        .map((el) => el.outerHTML),
    );
    expect(offenders).toEqual([]);
  });

  test('images have alternative text', async ({ page }) => {
    const missing = await page.evaluate(() =>
      Array.from(document.querySelectorAll('img:not([alt])')).map(
        (img) => img.outerHTML,
      ),
    );
    expect(missing).toEqual([]);
  });

  test('page works at 200% zoom without loss of content (WCAG 1.4.4)', async ({
    page,
  }) => {
    await page.setViewportSize({ width: 640, height: 480 });
    await page.evaluate(() => {
      document.body.style.zoom = '2';
    });
    await expect(
      page.getByRole('heading', { name: 'Trail Runner 2', level: 1 }),
    ).toBeVisible();
    await expect(
      page.getByRole('button', { name: /add to cart/i }),
    ).toBeVisible();
  });
});

